import{_ as o,o as d,c,a0 as t}from"./chunks/framework.DYS8d9tm.js";const m=JSON.parse('{"title":"🚀 WealthFam Product Backlog","description":"","frontmatter":{},"headers":[],"relativePath":"Management/backlog.md","filePath":"Management/backlog.md"}'),a={name:"Management/backlog.md"};function i(n,e,r,s,l,u){return d(),c("div",null,[...e[0]||(e[0]=[t('<h1 id="🚀-wealthfam-product-backlog" tabindex="-1">🚀 WealthFam Product Backlog <a class="header-anchor" href="#🚀-wealthfam-product-backlog" aria-label="Permalink to &quot;🚀 WealthFam Product Backlog&quot;">​</a></h1><p><em>Tracks active bugs, tech debt, upcoming enhancements, and deferred work across <code>Backend</code>, <code>Parser</code>, <code>Web-App</code>, and <code>Mobile-App</code>. Per <a href="./PRACTICES.html">PRACTICES.md</a>, resolved items are archived in <a href="./CHANGELOG.html">CHANGELOG.md</a>.</em></p><blockquote><p><strong>How to use this backlog:</strong> Related items are grouped into <strong>Parent Tasks (Epics)</strong> with <strong>Child Tasks</strong> so overlapping files and invariants are fixed together in one branch/PR. Use the <strong>Execution &amp; Mutual Exclusivity Matrix</strong> below to pick parallelizable work safely.</p></blockquote><hr><h2 id="🗺️-execution-order-mutual-exclusivity-matrix" tabindex="-1">🗺️ Execution Order &amp; Mutual Exclusivity Matrix <a class="header-anchor" href="#🗺️-execution-order-mutual-exclusivity-matrix" aria-label="Permalink to &quot;🗺️ Execution Order &amp; Mutual Exclusivity Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Parent Task</th><th>Priority</th><th>Platforms</th><th>Depends On</th><th>Mutually Exclusive (Safe in Parallel With)</th></tr></thead><tbody><tr><td><strong>P0-A</strong></td><td>Multi-Tenancy, RBAC, Crypto &amp; Mobile Privacy Hotfixes</td><td>🚨 P0</td><td>Backend, Mobile</td><td>None</td><td>P0-B <em>(Web/Mobile children only; Backend overlaps)</em></td></tr><tr><td><strong>P0-B</strong></td><td>Runtime Crashes, Destructive Vault Detach &amp; Mobile 403 Logout</td><td>🚨 P0</td><td>Backend, Web, Mobile</td><td>None</td><td>P0-A <em>(Web/Mobile children only; Backend overlaps)</em></td></tr><tr><td><strong>P1-A</strong></td><td>Core Ledger, Smart Balance Engine &amp; Transfer Integrity</td><td>🔴 P1</td><td>Backend, Web, Mobile</td><td>P0-A, P0-B</td><td>P1-B <em>(P1-B.1, P1-B.4 only)</em>, P1-D, P2-B <em>(P2-B.1 only)</em>, P2-C</td></tr><tr><td><strong>P1-B</strong></td><td>Ingestion Pipeline, Parser Fixes &amp; Mobile SMS Sync Hardening</td><td>🔴 P1</td><td>Parser, Backend, Mobile</td><td>P0-A, P1-A <em>(for P1-B.2 &amp; P1-B.3 Backend anchor guards)</em></td><td>P1-A <em>(P1-B.1, P1-B.4 only)</em>, P1-C, P1-D, P1-E, P2-A, P2-B, P2-C</td></tr><tr><td><strong>P1-C</strong></td><td>Credit Card Billing, Statement Math &amp; Mark-Paid Flow</td><td>🔴 P1</td><td>Backend, Web, Mobile</td><td>P1-A <em>(for accurate CC <code>balance</code>)</em></td><td>P1-B, P1-D, P1-E, P2-C</td></tr><tr><td><strong>P1-D</strong></td><td>Financial Instruments: Loans, FD/RD/PF &amp; MF Tax/SIP</td><td>🔴 P1</td><td>Backend, Web, Mobile</td><td>P0-A, P0-B</td><td>P1-A, P1-B, P1-C, P2-B <em>(P2-B.1 only)</em>, P2-C</td></tr><tr><td><strong>P1-E</strong></td><td>Net Worth, Analytics, Budgets &amp; Recurring Parity</td><td>🔴 P1</td><td>Backend, Web, Mobile</td><td>P1-D <em>(P1-D.2 FD/RD valuation)</em></td><td>P1-B, P1-C, P2-B, P2-C</td></tr><tr><td><strong>P2-A</strong></td><td>Web-App Data/Timezone, Filter &amp; Account View Fixes</td><td>🟠 P2</td><td>Web</td><td>None</td><td>P1-B, P2-B, P2-C</td></tr><tr><td><strong>P2-B</strong></td><td>Mobile Gateway Deduplication &amp; API Route Normalization</td><td>🟠 P2</td><td>Backend (Mobile), Mobile</td><td>P0-A, P0-B</td><td>P1-A <em>(P2-B.1 only)</em>, P1-B, P1-D <em>(P2-B.1 only)</em>, P1-E, P2-A, P2-C</td></tr><tr><td><strong>P2-C</strong></td><td>Ops &amp; Data Hygiene (14-Day Log Auto-Prune)</td><td>🟠 P2</td><td>Backend, Web</td><td>P0-A <em>(scheduler fix)</em></td><td>Everything else</td></tr><tr><td><strong>P3</strong></td><td>Long-Term Roadmap (MCP, WealthFam Score, Multi-Currency FX)</td><td>🟣 P3</td><td>Full Stack</td><td>P1-E <em>(for P3-2, P3-3; P3-1 is independent)</em></td><td>—</td></tr></tbody></table><hr><h2 id="🚨-p0-—-critical-security-privacy-crashes-data-loss-fix-first" tabindex="-1">🚨 P0 — Critical Security, Privacy, Crashes &amp; Data Loss (Fix First) <a class="header-anchor" href="#🚨-p0-—-critical-security-privacy-crashes-data-loss-fix-first" aria-label="Permalink to &quot;🚨 P0 — Critical Security, Privacy, Crashes &amp; Data Loss (Fix First)&quot;">​</a></h2><h3 id="p0-a-multi-tenancy-rbac-crypto-isolation-mobile-privacy-hotfixes" tabindex="-1">P0-A: Multi-Tenancy, RBAC, Crypto Isolation &amp; Mobile Privacy Hotfixes <a class="header-anchor" href="#p0-a-multi-tenancy-rbac-crypto-isolation-mobile-privacy-hotfixes" aria-label="Permalink to &quot;P0-A: Multi-Tenancy, RBAC, Crypto Isolation &amp; Mobile Privacy Hotfixes&quot;">​</a></h3><p><em>Target: <code>Backend</code> (<code>transaction_service.py</code>, <code>investment_goal_service.py</code>, <code>scheduler.py</code>, <code>email_sync.py</code>, <code>mobile/api/router.py</code>), <code>Mobile-App</code> (<code>auth_service.dart</code>, <code>foreground_task_handler.dart</code>)</em></p><ul><li>[ ] <strong>[P0-A.1] Cross-Tenant Account Balance Mutation &amp; Account Hijack</strong> <code>[Backend]</code>: <code>TransactionService.update_transaction</code> (<code>transaction_service.py:887-930, 958-959, 998-1016</code>) and <code>create_transaction</code> (<code>:223-239, 265-281</code>) assign/mutate <code>account_id</code> and <code>to_account_id</code> without verifying <code>Account.tenant_id == tenant_id</code>, and additional unscoped <code>Account</code> <code>.filter()</code>/<code>.update()</code> calls exist at <code>:260, :297, :308, :699, :722, :928, :993, :1014, :1275</code> plus <code>to_account_id</code> in <code>batch_update_category_and_create_rule</code> (<code>:1393-1458</code>). <em>Fix</em>: Validate both source and target accounts against <code>(tenant_id, is_deleted=False)</code> upfront regardless of <code>update_balance</code>, and scope every <code>Account</code> query/update in <code>transaction_service.py</code> by <code>tenant_id</code>.</li><li>[ ] <strong>[P0-A.2] Cross-Tenant Goal Linking in Aggregate MF Branch</strong> <code>[Backend]</code>: <code>InvestmentGoalService.link_holding_to_goal</code> (<code>investment_goal_service.py:231-242</code>) updates <code>h.goal_id = goal_id</code> in the <code>group_&lt;scheme_code&gt;</code> branch without verifying <code>goal_id</code> belongs to <code>tenant_id</code>. <em>Fix</em>: Hoist the existing <code>InvestmentGoal.tenant_id == tenant_id</code> validation (<code>:254-261</code>) above the aggregate branch while preserving <code>goal_id=None</code> unlinking.</li><li>[ ] <strong>[P0-A.3] Scheduler &amp; Email Sync Crypto Context Poisoning + Missing Rollbacks</strong> <code>[Backend]</code>: In <code>scheduler.py</code> (<code>auto_sync_job</code>, <code>daily_recurrence_check</code>, <code>mutual_fund_sync_job</code>, <code>pulse_check_job</code>, <code>daily_summary_job</code>) and <code>email_sync.py</code> (<code>sync_emails</code>, <code>ThreadPoolExecutor</code> at <code>:219-220</code>), <code>_current_tenant_var</code> is left on the last tenant or dropped across threads, corrupting/failing <code>EncryptedString</code> decryption; shared <code>db</code> sessions also lack <code>db.rollback()</code> on exceptions, poisoning subsequent tenants. <em>Fix</em>: Add a <code>crypto_tenant_context(tenant_id)</code> context manager in <code>crypto/types.py</code> (resetting the <code>ContextVar</code> token in <code>finally</code>), propagate <code>contextvars.copy_context().run(...)</code> into worker threads, use per-tenant sessions with explicit <code>db.rollback()</code> in every <code>except</code> block, and gracefully skip sealed tenants (<code>TenantSealedException</code>).</li><li>[ ] <strong>[P0-A.4] Missing RBAC &amp; Tenant Checks on Mobile Device Management</strong> <code>[Backend]</code>: <code>delete_device</code>, <code>update_device</code>, <code>toggle_device_enabled</code>, and <code>toggle_device_ignored</code> (<code>Backend/app/modules/mobile/api/router.py:552-674</code>) omit the <code>CHILD</code> role guard, and <code>update_device</code>/<code>assign_device_user</code> set <code>device.user_id</code> without checking <code>User.tenant_id == current_user.tenant_id</code>. <em>Fix</em>: Block <code>CHILD</code> role consistently (normalized <code>.upper() == &quot;CHILD&quot;</code>) and validate non-empty <code>user_id</code> belongs to the caller&#39;s tenant (allowing <code>None</code>/empty to unassign).</li><li>[ ] <strong>[P0-A.5] Mobile Logout Leaves Background SMS Service Running With Old Token</strong> <code>[Mobile]</code>: <code>AuthService.logout()</code> (<code>Mobile-App/lib/modules/auth/services/auth_service.dart:443-470</code>) never clears <code>FlutterForegroundTask</code> storage (<code>access_token</code>) or calls <code>ForegroundServiceWrapper.stop()</code>, so the background isolate continues polling and forwarding incoming SMS after logout. <em>Fix</em>: Stop the foreground service and wipe <code>FlutterForegroundTask</code> persisted keys (guarded with <code>!kIsWeb &amp;&amp; Platform.isAndroid</code> in <code>try/catch</code>), and clear <code>sms_offline_queue</code> in <code>SharedPreferences</code> on logout so queued SMS aren&#39;t flushed under a different account.</li><li>[ ] <strong>[P0-A.6] Mobile Catch-Up Scan Forwards Non-Financial Personal SMS</strong> <code>[Mobile]</code>: <code>SyncTaskHandler._performCatchUpScan()</code> (<code>foreground_task_handler.dart:110-178</code>) only filters pure OTPs and never applies <code>_transactionPattern</code> (defined at <code>:50</code>), sending all personal SMS from the last 24h to <code>/api/v1/ingestion/sms</code>. <em>Fix</em>: Require <code>_transactionPattern.hasMatch(body)</code> in catch-up scan to match <code>SmsReceiver.kt</code>.</li></ul><h3 id="p0-b-guaranteed-runtime-crashes-destructive-vault-action-mobile-403-logout" tabindex="-1">P0-B: Guaranteed Runtime Crashes, Destructive Vault Action &amp; Mobile 403 Logout <a class="header-anchor" href="#p0-b-guaranteed-runtime-crashes-destructive-vault-action-mobile-403-logout" aria-label="Permalink to &quot;P0-B: Guaranteed Runtime Crashes, Destructive Vault Action &amp; Mobile 403 Logout&quot;">​</a></h3><p><em>Target: <code>Backend</code>, <code>Web-App</code>, <code>Mobile-App</code></em></p><ul><li>[ ] <strong>[P0-B.1] Backend <code>NameError</code> Crashes on Goal Delete, Expense Group Delete &amp; Email Sync</strong> <code>[Backend]</code>: Missing <code>timezone</code> import in <code>investment_goal_service.py:215</code> and <code>expense_group_service.py:93</code>, and undefined <code>logger</code> in <code>email_sync.py:204, 226</code>. <em>Fix</em>: Import <code>from backend.app.core import timezone</code> (not <code>datetime.timezone</code>), add module-level <code>logger = logging.getLogger(__name__)</code> in <code>email_sync.py</code>, and add regression tests.</li><li>[ ] <strong>[P0-B.2] &quot;Detach Document&quot; Permanently Deletes Vault File</strong> <code>[Web]</code>: <code>TransactionModal.vue:175-183, 571</code> calls <code>financeApi.deleteDocument(docId)</code> instead of <code>financeApi.linkDocToTransaction(docId, null)</code> when detaching a receipt/document. <em>Fix</em>: Unlink the document instead of deleting it from the Vault, and update the button icon from <code>&lt;Trash2&gt;</code> to <code>&lt;Unlink&gt;</code>.</li><li>[ ] <strong>[P0-B.3] Mobile HTTP <code>403 Forbidden</code> Forces Immediate Logout + Family Account 403 Bug</strong> <code>[Mobile]</code> <code>[Backend]</code>: <code>network_resilience.dart:76-79, 155-158</code> calls <code>onUnauthorized()</code> (which runs <code>_auth.logout()</code>) on <code>403</code> responses. Combined with <code>POST /api/v1/mobile/transactions</code> (<code>mobile/api/router.py:1381-1383</code>, and a similar document <code>owner_id</code> check at <code>:2450</code>) blocking <code>OWNER</code>/<code>ADULT</code> users from acting on a spouse/child account, selecting a family account logs the user out. <em>Fix</em>: Trigger logout only on unrecoverable <code>401</code> (return <code>Left(SecurityFailure(...))</code> on <code>403</code>), allow <code>OWNER</code>/<code>ADULT</code> to act on family accounts in <code>mobile/api/router.py:1381</code>, and reuse <code>CoreVaultService.can_modify_document(doc, current_user)</code> at <code>:2450</code> (preserving private adult doc isolation).</li></ul><hr><h2 id="🔴-p1-—-high-priority-core-financial-accuracy-ingestion-client-parity" tabindex="-1">🔴 P1 — High Priority (Core Financial Accuracy, Ingestion &amp; Client Parity) <a class="header-anchor" href="#🔴-p1-—-high-priority-core-financial-accuracy-ingestion-client-parity" aria-label="Permalink to &quot;🔴 P1 — High Priority (Core Financial Accuracy, Ingestion &amp; Client Parity)&quot;">​</a></h2><h3 id="p1-a-core-ledger-smart-balance-engine-transfer-integrity" tabindex="-1">P1-A: Core Ledger, Smart Balance Engine &amp; Transfer Integrity <a class="header-anchor" href="#p1-a-core-ledger-smart-balance-engine-transfer-integrity" aria-label="Permalink to &quot;P1-A: Core Ledger, Smart Balance Engine &amp; Transfer Integrity&quot;">​</a></h3><p><em>Foundational epic — land before P1-B.2, P1-B.3, and P1-C so all balance writes use the same anchor &amp; sign contract.</em></p><ul><li>[ ] <strong>[P1-A.1] Smart Balance Mode (<code>CALCULATED</code> vs <code>DERIVED</code>) + Anchor Boundary Fix</strong> <code>[Backend]</code> <code>[Web]</code> <code>[Mobile]</code>: Every account currently enforces <code>txn_date &gt;= last_synced_at</code> (even when <code>last_synced_at</code> is <code>created_at</code>), dropping backdated CC/Wallet txns, double-counting <code>==</code> boundary txns, and wiping post-anchor txns on backdated anchors. <em>Fix</em>: Add <code>balance_mode</code> (<code>CALCULATED</code> | <code>DERIVED</code>) and <code>balance_source</code> (<code>CALCULATED</code> | <code>STATEMENT</code> | <code>SMS</code> | <code>EMAIL</code> | <code>MANUAL_OVERRIDE</code>) on <code>Account</code>. <code>CALCULATED</code> (default for CC/Wallet/manual without <code>as_of</code>): <code>opening_balance + SUM(all active txns)</code>. <code>DERIVED</code> (Bank Statement/SMS/Email or explicit <code>as_of</code> / <code>MANUAL_OVERRIDE</code> on any account including CC/Wallet — never CC SMS): <code>last_synced_balance + SUM(active txns strictly &gt; last_synced_at)</code> (anchor date-only statements at end-of-day so same-day earlier txns aren&#39;t re-added). Centralize <code>balance_delta()</code>, <code>counts_toward_balance()</code>, and <code>recalculate_balance()</code> in <code>AccountService</code>, call <code>recalculate_balance()</code> inside <code>override_balance</code>, wire new columns with v1.0 defaults into <code>BackupService</code>, and expose <code>balance_mode</code>/<code>balance_source</code> in <code>Web-App</code> and <code>Mobile-App</code> (<code>account_model.dart</code>, <code>adjust_balance_sheet.dart</code>).</li><li>[ ] <strong>[P1-A.2] <code>Transaction.type</code> Sign Invariant (<code>DEBIT</code>/<code>CREDIT</code>)</strong> <code>[Backend]</code> <code>[Mobile]</code>: <code>TransactionService.create_transaction</code> pops <code>&#39;type&#39;</code> before DB insert, saving positive credits with default <code>type = &#39;DEBIT&#39;</code>; in <code>Mobile-App</code>, <code>TransactionModel.isExpense</code>/<code>isIncome</code> (<code>transaction_model.dart:68-69</code>) uses <code>||</code>, making both <code>true</code> simultaneously. <em>Fix</em>: Derive <code>Transaction.type</code> from <code>amount</code> sign (<code>&lt; 0</code> → <code>DEBIT</code>, <code>&gt;= 0</code> → <code>CREDIT</code>) via SQLAlchemy <code>before_insert</code>/<code>before_update</code> listener in <code>models.py</code>, set <code>data[&#39;type&#39;]</code> pre-flush in <code>create_transaction</code>, derive <code>t_type</code> from <code>t_amt</code> before computing <code>t_sig</code> in <code>BackupService</code> merge-mode dedupe, run a one-time backfill migration, and simplify <code>TransactionModel.isExpense</code>/<code>isIncome</code> to check <code>amount</code> sign cleanly.</li><li>[ ] <strong>[P1-A.3] Account Creation <code>as_of</code> Date, Type Switching &amp; Backup Balance Sync</strong> <code>[Backend]</code> <code>[Web]</code> <code>[Mobile]</code>: <ul><li>Support optional <code>as_of</code> date/timestamp (rejecting future dates) in <code>AccountCreate</code>/<code>CreditCardCreate</code> and expose in <code>Web-App</code> (<code>AccountEditModal.vue</code>, <code>CreditCards.vue</code>) and <code>Mobile-App</code> (<code>add_edit_account_sheet.dart</code>, <code>accounts_repository.dart</code>).</li><li>Fix <code>Web-App</code> <code>AccountEditModal.vue:26-37, 106-108</code> sending <code>balance</code>/<code>account_mask</code> instead of <code>initial_balance</code>/<code>card_last_4</code> when creating a Credit Card (currently silently dropped).</li><li>Fix <code>Mobile-App</code> <code>add_edit_account_sheet.dart:133-145</code> stamping a <code>MANUAL</code> balance anchor at <code>now()</code> when only <code>creditLimit</code> changed, and <code>accounts_repository.dart:134-145</code> hitting 404 when changing an existing account&#39;s type to <code>CREDIT_CARD</code>.</li><li>Trigger <code>AccountService.recalculate_balance()</code> in <code>AccountService.update_account</code> when <code>Account.type</code> crosses Asset ↔ Liability, and at the end of <code>.wfam</code> restore in <code>BackupService</code>.</li></ul></li><li>[ ] <strong>[P1-A.4] Bulk Delete, Transfer Sign &amp; Orphan Integrity</strong> <code>[Backend]</code> <code>[Web]</code>: <ul><li><code>TransactionService.bulk_delete_transactions</code>: filter <code>is_deleted == False</code> and scope account lookup by <code>tenant_id</code> (stops double-reverting deleted txns).</li><li><code>TransferService.create_transfer</code>: normalize with <code>abs(Decimal(str(amount)))</code> and handle inflow (<code>pending.amount &gt; 0</code>) in <code>approve_transfer</code>.</li><li><code>batch_update_category_and_create_rule</code> (<code>transaction_service.py</code>): call <code>TransferDetectionService.create_counterpart_leg(..., commit=False)</code> when <code>to_account_id</code> is passed.</li><li><code>TransactionService.update_transaction</code> (<code>:932-948</code>): clear <code>db_txn.linked_transaction_id = None</code> when unlinking (<code>is_transfer=False</code>) and sync mirrored counterpart amount/date on edit.</li><li>Orphan integrity: clean up transfer counterparts, detail soft-deletes, and dangling FKs (<code>autopay_bank_account_id</code>, <code>linked_payout_account_id</code>, <code>linked_account_id</code>) on account deletion; make <code>RuleExecutor</code> unlink both legs; exclude soft-deleted accounts in <code>TransferDetectionService</code>; fix <code>Web-App</code> <code>Transfers.vue:713-717</code> null-dereference crash when <code>suggested_destination</code> is null.</li></ul></li><li>[ ] <strong>[P1-A.5] Periodic Balance-Drift Audit &amp; Admin Reconcile Check</strong> <code>[Backend]</code>: Add a read-only balance-drift audit script/check (flagging drift &gt; ₹0.01, excluding non-ledger <code>INVESTMENT</code>/<code>FD</code>/<code>RD</code>/<code>PF</code> accounts) and an optional opt-in admin reconcile trigger comparing stored <code>Account.balance</code> against the <code>balance_mode</code> formula (<code>P1-A.1</code>).</li></ul><h3 id="p1-b-ingestion-pipeline-parser-fixes-mobile-sms-sync-hardening" tabindex="-1">P1-B: Ingestion Pipeline, Parser Fixes &amp; Mobile SMS Sync Hardening <a class="header-anchor" href="#p1-b-ingestion-pipeline-parser-fixes-mobile-sms-sync-hardening" aria-label="Permalink to &quot;P1-B: Ingestion Pipeline, Parser Fixes &amp; Mobile SMS Sync Hardening&quot;">​</a></h3><p><em>Children <code>P1-B.1</code> (<code>Parser/</code>) and <code>P1-B.4</code> (<code>Mobile-App</code>) are fully mutually exclusive and can start immediately; <code>P1-B.2</code>/<code>P1-B.3</code> touch <code>Backend/ingestion/</code>.</em></p><ul><li>[ ] <strong>[P1-B.1] Parser Date/Timezone Corruption &amp; Batch Pipeline Field Loss</strong> <code>[Parser]</code>: <ul><li>Fix <code>BaseParser._parse_date</code> (<code>base_compat.py:154-161</code>) raising <code>AttributeError</code> on string <code>date_hint</code> (<code>received_at</code>), which silently discards parsed transaction dates and overwrites them with <code>received_at</code>.</li><li>Convert IST bank SMS/email timestamps to UTC (<code>Asia/Kolkata</code> → <code>UTC</code>) in <code>base_compat.py</code> / <code>generic.py</code> instead of returning naive datetimes that shift +5h30m when stamped UTC.</li><li>Fix <code>BatchIngestionPipeline.run_batch</code> (<code>batch_pipeline.py:69-85</code>) dropping <code>ref_id</code>, <code>balance</code>, <code>credit_limit</code>, <code>category</code>, and skipping normalizer/guesser/time-enrichment on email batch sync.</li><li>Pass <code>sender=sender</code> to <code>p.can_handle(...)</code> in <code>IngestionPipeline.run</code> (<code>pipeline.py:257</code>) so domain-matched email parsers (<code>OneCard</code>, <code>Cred</code>, <code>YesBank</code>) actually match.</li><li>Add compact date formats (<code>%d%b%y</code>, <code>%d%b%Y</code>) for <code>SbiSmsParser</code> (<code>sbi.py</code>) and fix <code>SliceSmsParser._parse_date</code> signature mismatch (<code>slice.py:67</code>).</li></ul></li><li>[ ] <strong>[P1-B.2] Credit Card SMS &quot;Available Limit&quot; Overwrites Card Balance</strong> <code>[Parser]</code> <code>[Backend]</code>: Drop <code>balance</code> capture on CC available-limit patterns in <code>Parser/parsers/bank/{onecard,hsbc,scb}.py</code>, exclude <code>Avl/Avbl/Avail/Available</code> prefixes in <code>hdfc.py</code>, and block <code>IngestionService</code> / <code>import_csv</code> from overwriting <code>CREDIT_CARD</code> balance from <code>parsed.balance</code> (sync <code>credit_limit</code> only).</li><li>[ ] <strong>[P1-B.3] Backend Ingestion Deduplication, Account Matching &amp; PDF Statement Sign Guards</strong> <code>[Backend]</code> <code>[Parser]</code>: <ul><li><code>import_csv</code> (<code>ingestion/router.py</code>): normalize <code>txn_date</code> to UTC and run <code>TransactionDeduplicator.check_raw_duplicate</code> <em>before</em> writing <code>last_synced_balance</code>/<code>BalanceSnapshot</code>.</li><li><code>TransactionDeduplicator</code> (<code>deduplicator.py</code>): scope <code>external_id</code>/<code>ref_id</code> duplicate lookups by <code>account_id</code> so cross-account same-UTR transfer legs aren&#39;t dropped.</li><li><code>IngestionService</code> (<code>ingestion/services.py:174-184, 305, 337</code>): filter <code>Account.is_deleted == False</code> in <code>match_account</code> and <code>TransferDetector</code> lookup, reject empty-digit masks (e.g. <code>&quot;XX&quot;</code> matching everything via <code>endswith(&quot;&quot;)</code>), and apply <code>ensure_utc()</code> before comparing <code>parsed.date &lt; last_synced_at</code>.</li><li>PDF Statement Import &amp; Reconciliation (<code>statements.py</code>, <code>statement_processor.py</code>): enforce <code>-abs(st.amount)</code> / <code>abs(st.amount)</code> based on <code>st.type</code>, optionally anchor closing balance for <code>DERIVED</code> bank accounts, and fix <code>Parser/parsers/statement/parsers/icici_savings.py:57-61</code> <code>.find()</code> column misclassification.</li></ul></li><li>[ ] <strong>[P1-B.4] Mobile Android SMS Sync Hardening (Auth Refresh, Race &amp; Atomic Relay)</strong> <code>[Mobile]</code>: <ul><li>Wire 401 token refresh/session recovery into <code>foreground_task_handler.dart:497-533, 762-768</code> and <code>sms_service.dart:918-963</code> (stops infinite 401 offline queue retry loop).</li><li>Eliminate cross-isolate TOCTOU duplicate submission race between <code>SyncTaskHandler._checkNativeSmsQueue()</code> and <code>SmsService._drainNativeRelayFiles()</code> (plus unawaited <code>_performCatchUpScan()</code>).</li><li>Use atomic temp-file + rename writes in <code>SmsReceiver.kt:328-329</code> and stop deleting relay files on transient <code>FormatException</code>/IO errors.</li><li>Normalize <code>computeHash</code> (<code>YYYYMMDDHH</code>) to <code>.toUtc()</code> and unify <code>received_at</code> between foreground and background paths.</li></ul></li></ul><h3 id="p1-c-credit-card-billing-statement-math-mark-statement-as-paid-flow" tabindex="-1">P1-C: Credit Card Billing, Statement Math &amp; &quot;Mark Statement as Paid&quot; Flow <a class="header-anchor" href="#p1-c-credit-card-billing-statement-math-mark-statement-as-paid-flow" aria-label="Permalink to &quot;P1-C: Credit Card Billing, Statement Math &amp; &quot;Mark Statement as Paid&quot; Flow&quot;">​</a></h3><p><em>Mutually exclusive from P1-B, P1-D, and P1-E; best landed after P1-A.1.</em></p><ul><li>[ ] <strong>[P1-C.1] Credit Card Statement Balance, IST Cycle Cutoffs &amp; Available Limit Math</strong> <code>[Backend]</code> <code>[Web]</code> <code>[Mobile]</code>: <ul><li>Backend (<code>analytics/credit.py</code>, <code>CreditCardService.get_cycle_transactions</code>, <code>core/timezone.py</code>): centralize <code>DEFAULT_BILLING_TZ = &quot;Asia/Kolkata&quot;</code> in <code>core/timezone.py</code> for calendar boundaries converted to UTC, include bill payments regardless of <code>exclude_from_reports</code> (ledger state, not expense analytics), separate bill payments from merchant refunds, compute <code>net_unbilled = unbilled_debits - unbilled_refunds</code> and remaining <code>statement_balance = max(0, balance - max(0, net_unbilled))</code> (so unbilled merchant refunds don&#39;t understate unpaid statement due), and don&#39;t advance <code>due_date</code> while an overdue statement is unpaid.</li><li>Web-App: fix <code>CreditWalletWidget.vue</code> (compute available credit &amp; utilization from <code>card.balance</code>, fix overdue <code>days_until_due &lt; 0</code> label, route Details/Manage to <code>/credit-cards/:id</code>), <code>CreditCards.vue:840</code> (<code>?? 999</code> instead of <code>|| 999</code> so cards due today sort first), and <code>WealthCompass.vue:79-81</code> (clamp over-limit utilization to <code>[0, 100]</code>).</li><li>Mobile-App: verify <code>account_detail_screen.dart</code> <code>activeCycleInfo</code> display against updated backend fields.</li></ul></li><li>[ ] <strong>[P1-C.2] Credit Card &quot;Mark Statement as Paid&quot; (Link Existing Txn or No Source Account)</strong> <code>[Backend]</code> <code>[Web]</code> <code>[Mobile]</code>: <ul><li>Backend: implement <code>get_payment_candidates</code> and <code>mark_statement_paid</code> on <code>CreditCardService</code> (keeping <code>AccountService</code> instrument-agnostic), expose <code>/credit-cards/{id}/payment-candidates</code> and <code>/credit-cards/{id}/mark-paid</code> (+ <code>/api/v1/mobile/*</code> mirrors, duplicate card-credit guard, and automatic placeholder claiming coordinated with <code>TransactionDeduplicator</code> when issuer credit SMS arrives later).</li><li>Web-App: wire into <code>CreditWalletWidget</code>, <code>CreditCards</code>, <code>CreditCardDetails</code>, and <code>AccountDetails</code> (fixing the currently non-functional <code>record_transaction</code> toggle in <code>AccountDetails.vue:344-369</code>).</li><li>Mobile-App: update <code>pay_bill_sheet.dart</code>, <code>accounts_repository.dart</code>, <code>accounts_service.dart</code>, <code>account_detail_screen.dart</code>, and <code>accounts_screen.dart</code> to support linking an existing bank debit or marking paid without a source account.</li></ul></li></ul><h3 id="p1-d-financial-instruments-accuracy-—-loans-deposits-fd-rd-pf-mutual-funds" tabindex="-1">P1-D: Financial Instruments Accuracy — Loans, Deposits (FD/RD), PF &amp; Mutual Funds <a class="header-anchor" href="#p1-d-financial-instruments-accuracy-—-loans-deposits-fd-rd-pf-mutual-funds" aria-label="Permalink to &quot;P1-D: Financial Instruments Accuracy — Loans, Deposits (FD/RD), PF &amp; Mutual Funds&quot;">​</a></h3><p><em>Children <code>P1-D.1</code>, <code>P1-D.2</code>, and <code>P1-D.3</code> are mutually exclusive from each other and from P1-A/B/C.</em></p><ul><li>[ ] <strong>[P1-D.1] Loan EMI Principal/Interest Split, Prepayment &amp; Date Clamp</strong> <code>[Backend]</code> <code>[Web]</code> <code>[Mobile]</code>: <ul><li>Backend (<code>loan_service.py</code>): split regular EMI repayments into <code>interest_part</code> + <code>principal_part</code> — keep a single <code>-EMI</code> bank debit (1:1 SMS/statement matching; cash-flow Living Expense) and credit only <code>principal_part</code> to the Loan account; add <code>is_prepayment</code> (100% principal, with <code>is_emi=False</code> so <code>_generate_amortization_schedule</code> doesn&#39;t falsely mark unpaid EMI months <code>PAID</code>); and clamp <code>emi_date</code> days 29–31 in <code>_map_to_read_schema</code> for shorter months.</li><li>Web-App (<code>LoanRepaymentModal.vue</code>, <code>LoanDetails.vue</code>): add <code>is_prepayment</code> toggle, decimal <code>step=&quot;any&quot;</code>, and principal/interest split preview.</li><li>Mobile-App (<code>record_repayment_sheet.dart</code>, <code>loans_repository.dart</code>, <code>loans_service.dart</code>, <code>loan_model.dart:194-212</code>): wire <code>is_prepayment</code> + split preview, and fix <code>LoanDetailModel.fromJson</code> omitting <code>lenderName</code> and <code>loanAccountNumber</code>.</li></ul></li><li>[ ] <strong>[P1-D.2] FD Compounding, RD Installment Valuation &amp; Anchor Sync</strong> <code>[Backend]</code> <code>[Web]</code> <code>[Mobile]</code>: <ul><li>Backend (<code>fixed_deposit_service.py</code>, <code>provident_fund_service.py</code>): fix <code>timezone.timedelta</code> <code>AttributeError</code> crash (<code>fixed_deposit_service.py:23, 211</code>), add shared <code>Decimal</code>-based <code>FixedDepositService.valuation()</code> for compound FD + multi-installment RD, save/backfill <code>monthly_deposit</code> carefully (avoiding 12x inflation on legacy RDs), and sync <code>last_synced_balance</code>/<code>BalanceSnapshot</code> on FD &amp; PF updates.</li><li>Web-App (<code>Deposits.vue</code>): expose <code>compounding_frequency</code> &amp; <code>monthly_deposit</code> (for RDs), align <code>recalculateMaturity()</code> with backend compounding, and trigger on <code>deposit_type</code> change.</li><li>Mobile-App (<code>deposits_screen.dart:39, 91</code>, <code>deposit_model.dart</code>): render actual <code>compoundingFrequency</code> (remove hardcoded <code>&#39;Quarterly Compounded&#39;</code>) and show total RD invested principal.</li></ul></li><li>[ ] <strong>[P1-D.3] Mutual Fund LTCG Tax-Harvesting Pro-Rata &amp; SIP Liquidity Scope</strong> <code>[Backend]</code>: <ul><li><code>MFTaxService</code> (<code>mf_tax_service.py:267-277</code>): pro-rate <code>suggested_units_to_sell</code> (quantized to <code>0.0001</code>) and expose <code>suggested_redemption_value</code> when a lot&#39;s gain exceeds remaining ₹1.25L LTCG headroom instead of recommending full lot sale.</li><li><code>MFSipService</code>: scope liquidity check by <code>user_id</code> (<code>AccountType.BANK</code>) and verify each active SIP&#39;s <code>linked_account_id</code> balance individually against its 7d/30d commitments (falling back to user liquid bank total only when <code>linked_account_id is None</code>).</li></ul></li></ul><h3 id="p1-e-net-worth-analytics-budgets-recurring-parity" tabindex="-1">P1-E: Net Worth, Analytics, Budgets &amp; Recurring Parity <a class="header-anchor" href="#p1-e-net-worth-analytics-budgets-recurring-parity" aria-label="Permalink to &quot;P1-E: Net Worth, Analytics, Budgets &amp; Recurring Parity&quot;">​</a></h3><p><em>Depends on <code>P1-D.2</code> (<code>FixedDepositService.valuation()</code>) for Child <code>P1-E.1</code>; mutually exclusive from P1-B/C.</em></p><ul><li>[ ] <strong>[P1-E.1] Net Worth, History Timeline &amp; Goal Asset Parity</strong> <code>[Backend]</code> <code>[Web]</code>: <ul><li>Backend (<code>analytics/core.py</code>, <code>analytics/history.py</code>, <code>analytics/investments.py</code>, <code>investment_goal_service.py</code>): include <code>MutualFundHolding</code>, accrued FD/RD (<code>FixedDepositService.valuation()</code>), and PF consistently across <code>CoreAnalytics</code>, <code>HistoryAnalytics</code>, and <code>InvestmentAnalytics.get_family_wealth</code>; replay same-day post-snapshot transactions in <code>HistoryAnalytics</code>; block <code>CREDIT_CARD</code>/<code>LOAN</code> liability accounts as goal assets (<code>ValueError</code> → <code>400</code>).</li><li>Web-App: exclude <code>CREDIT_CARD</code>/<code>LOAN</code> in <code>InvestmentGoals.vue</code> / <code>LinkAssetModal.vue</code>; fix <code>Dashboard.vue</code> (<code>:92, 349-355</code> <code>% MoM</code> computing 1-day delta &amp; dividing by un-abs&#39;d negative net worth, and <code>:192-195</code> hardcoding green/gains when <code>mfPortfolio.pl &lt; 0</code>).</li></ul></li><li>[ ] <strong>[P1-E.2] Uncategorized Spending, Soft-Deleted Accounts &amp; Role Filter Parity</strong> <code>[Backend]</code>: <ul><li>Use consistent <code>outerjoin</code> on <code>Category</code> across <code>CoreAnalytics</code>, <code>SpendingAnalytics</code>, <code>HistoryAnalytics</code> (<code>get_budget_history:148</code>, <code>get_calendar_heatmap:269</code>), and <code>BudgetService</code> so uncategorized transactions match across Dashboard, Insights, and Budgets.</li><li>Always filter <code>Account.is_deleted == False</code> in Family/All analytics views and <code>Backend/app/modules/mobile/services/expense_group_service.py</code> (also change mobile <code>delete_expense_group</code> from hard-delete to soft-delete).</li><li>Fix <code>CHILD</code> role filters in <code>CoreAnalytics</code> and <code>TransactionService</code> (<code>&quot;CREDIT_CARD&quot;, &quot;LOAN&quot;</code> instead of <code>&quot;CREDIT&quot;</code>).</li></ul></li><li>[ ] <strong>[P1-E.3] Recurring Transactions Sign, Edit &amp; Forecast Window</strong> <code>[Backend]</code> <code>[Web]</code> <code>[Mobile]</code>: <ul><li>Backend (<code>recurring_service.py</code>, <code>analytics/core.py</code>): standardize <code>RecurringTransaction.amount</code> as positive magnitude (<code>abs(Decimal)</code>) on create/update, pass signed amount based on <code>item.type</code> (<code>DEBIT</code>/<code>CREDIT</code>), and project all occurrences within the forecast window on liquid accounts.</li><li>Web-App (<code>RecurringTab.vue</code>): add <code>type</code> selector, preserve <code>rec.type</code> and <code>next_run_date</code> on edit, and call <code>resetForm()</code> on &quot;Add Subscription&quot; so it doesn&#39;t overwrite the previously edited subscription.</li><li>Mobile-App (<code>analytics_recurring_tab.dart:831-835</code>): remove hardcoded <code>&#39;type&#39;: &#39;DEBIT&#39;</code> &amp; <code>-amt.abs()</code>; add <code>DEBIT</code>/<code>CREDIT</code> selector so editing recurring income doesn&#39;t convert it to a debit.</li></ul></li></ul><hr><h2 id="🟠-p2-—-medium-priority-client-polish-mobile-gateway-ops-hygiene" tabindex="-1">🟠 P2 — Medium Priority (Client Polish, Mobile Gateway &amp; Ops Hygiene) <a class="header-anchor" href="#🟠-p2-—-medium-priority-client-polish-mobile-gateway-ops-hygiene" aria-label="Permalink to &quot;🟠 P2 — Medium Priority (Client Polish, Mobile Gateway &amp; Ops Hygiene)&quot;">​</a></h2><h3 id="p2-a-web-app-timestamp-filter-account-view-bugs" tabindex="-1">P2-A: Web-App Timestamp, Filter &amp; Account View Bugs <a class="header-anchor" href="#p2-a-web-app-timestamp-filter-account-view-bugs" aria-label="Permalink to &quot;P2-A: Web-App Timestamp, Filter &amp; Account View Bugs&quot;">​</a></h3><p><em>Web-only (mutually exclusive from P1-B, P2-B, and P2-C); overlaps Web views (<code>CreditCards.vue</code>, <code>AccountDetails.vue</code>, <code>Deposits.vue</code>, <code>Dashboard.vue</code>) with P1-A/C/D/E.</em></p><ul><li>[ ] <strong>[P2-A.1] Transaction Edit Shifts Timestamp Backward by Local UTC Offset</strong> <code>[Web]</code>: <code>useTransactionModals.ts:127, 172</code> slices UTC ISO strings (<code>txn.date.slice(0, 16)</code>) into local wall time and re-converts via <code>toISOString()</code>, subtracting local offset (e.g. <code>-5h30m</code> in IST) on every save. <em>Fix</em>: Convert UTC → local wall time when populating the picker before converting back to UTC on submit.</li><li>[ ] <strong>[P2-A.2] &quot;Today&quot; Filter Includes Tomorrow &amp; Family Member Filter Leaks</strong> <code>[Web]</code>: <ul><li>Fix <code>useTransactionState.ts:149</code> (<code>case &#39;today&#39;</code> setting <code>end = today + 1</code> while backend <code>end_date</code> is inclusive).</li><li>Propagate <code>auth.selectedMemberId</code> and watch changes in <code>stores/finance.ts:32</code> (<code>fetchAll</code>), <code>CreditCards.vue:881</code>, <code>Deposits.vue:597</code>, <code>ProvidentFunds.vue:619</code>, and <code>Dashboard.vue:428</code> (<code>getRecurringTransactions</code>).</li></ul></li><li>[ ] <strong>[P2-A.3] <code>AccountDetails.vue</code> Blank Initial Chart, Un-Debounced Search &amp; Unverified Account Lookup</strong> <code>[Web]</code>: Default <code>periodFilter</code> to <code>&#39;month&#39;</code> for non-CC accounts (instead of <code>&#39;current&#39;</code>), debounce search and remove duplicate <code>@input=&quot;fetchTransactions&quot;</code> (which also passes DOM <code>InputEvent</code> as <code>options</code>, setting <code>page</code>/<code>limit</code> to <code>undefined</code>, and fires 4 requests/keystroke alongside <code>watch</code>), and pass <code>includeUnverified: true</code> in <code>fetchAccount()</code>.</li></ul><h3 id="p2-b-mobile-gateway-deduplication-api-route-normalization" tabindex="-1">P2-B: Mobile Gateway Deduplication &amp; API Route Normalization <a class="header-anchor" href="#p2-b-mobile-gateway-deduplication-api-route-normalization" aria-label="Permalink to &quot;P2-B: Mobile Gateway Deduplication &amp; API Route Normalization&quot;">​</a></h3><p><em><code>P2-B.1</code> is mutually exclusive from P1-A/B/D/E and P2-A/C; <code>P2-B.2</code> overlaps with P1-A.3, P1-C.2, and P1-D.1 on Mobile repositories/services.</em></p><ul><li>[ ] <strong>[P2-B.1] Deduplicate 4 Shadowed Routes in Mobile Gateway &amp; Fix Funds Member Filter</strong> <code>[Backend]</code> <code>[Mobile]</code>: <code>Backend/app/modules/mobile/api/router.py</code> registers duplicate handlers for <code>GET /funds</code> (<code>1419</code> vs <code>2671</code>), <code>GET /funds/{scheme_code}</code> (<code>1560</code> vs <code>2679</code>), <code>GET /categories</code> (<code>1671</code> vs <code>2610</code>), and <code>GET /vendor/stats</code> (<code>849</code> vs <code>2847</code>). Because <code>GET /funds</code> at <code>1419</code> expects <code>member_id</code> while <code>Mobile-App/funds_repository.dart:36-39</code> sends <code>user_id</code>, family member filtering on Mutual Funds is silently ignored. <em>Fix</em>: Remove shadowed duplicates (preserving <code>#L1419</code>&#39;s <code>MobileFundsResponse</code> shape with both <code>user_id</code> &amp; <code>member_id</code> query aliases for APK compatibility, and verifying <code>GET /categories</code> schema compatibility before dropping either handler).</li><li>[~] <strong>[P2-B.2] Mobile API Strictness &amp; Route Normalization</strong> <em>(In Progress / Deferred)</em> <code>[Mobile]</code> <code>[Backend]</code>: Migrate remaining direct <code>/api/v1/finance/*</code> and <code>/api/v1/ingestion/triage/*</code> calls across <code>Mobile-App</code> repositories/services (<code>accounts</code>, <code>categories</code>, <code>finance</code>, <code>funds</code>, <code>loans</code>, <code>statements</code>, <code>vault</code>) to dedicated <code>/api/v1/mobile/*</code> endpoints. <em>Explicitly exempt</em> shared cross-client endpoints: <code>/api/v1/ingestion/sms</code> (canonical per <code>sms_flow.md</code>), <code>/api/v1/auth/*</code>, <code>/api/v1/brands/*</code>, and <code>/api/v1/telemetry/*</code> (document exemption in <code>PRACTICES.md</code> §2).</li></ul><h3 id="p2-c-ops-data-hygiene" tabindex="-1">P2-C: Ops &amp; Data Hygiene <a class="header-anchor" href="#p2-c-ops-data-hygiene" aria-label="Permalink to &quot;P2-C: Ops &amp; Data Hygiene&quot;">​</a></h3><ul><li>[ ] <strong>[P2-C.1] 14-Day Auto-Prune for Ingestion &amp; Sync Logs</strong> <code>[Backend]</code> <code>[Web]</code>: Add a scheduled background job in <code>scheduler.py</code> (configurable via <code>INGESTION_LOG_RETENTION_DAYS = 14</code> in <code>config.py</code>) to prune <code>email_sync_item_logs</code> <em>before</em> <code>email_sync_logs</code> (no <code>ondelete=&quot;CASCADE&quot;</code> FK) and <code>ingestion_events</code> older than 14 days, and cap <code>Web-App/src/views/settings/IngestionsSettings.vue</code> date filters to a maximum 14-day review window with a subtle retention notice.</li></ul><hr><h2 id="🟣-p3-—-long-term-roadmap-future-capabilities" tabindex="-1">🟣 P3 — Long-Term Roadmap &amp; Future Capabilities <a class="header-anchor" href="#🟣-p3-—-long-term-roadmap-future-capabilities" aria-label="Permalink to &quot;🟣 P3 — Long-Term Roadmap &amp; Future Capabilities&quot;">​</a></h2><h3 id="🛠️-new-infrastructure-tooling" tabindex="-1">🛠️ New Infrastructure &amp; Tooling <a class="header-anchor" href="#🛠️-new-infrastructure-tooling" aria-label="Permalink to &quot;🛠️ New Infrastructure &amp; Tooling&quot;">​</a></h3><ul><li>[ ] <strong>[P3-1] MCP Server (FastAPI Module)</strong>: Implement a Model Context Protocol (MCP) server leveraging FastAPI as a distinct, decoupled integration module.</li></ul><h3 id="💎-advanced-fintech-features" tabindex="-1">💎 Advanced Fintech Features <a class="header-anchor" href="#💎-advanced-fintech-features" aria-label="Permalink to &quot;💎 Advanced Fintech Features&quot;">​</a></h3><ul><li>[ ] <strong>[P3-2] Financial Health Score</strong>: Create a proprietary &quot;WealthFam Score&quot; based on savings rate, emergency runway months, and debt-to-income ratios.</li><li>[ ] <strong>[P3-3] Multi-Currency FX Normalization</strong>: Convert non-base-currency accounts (<code>Account.currency != base_currency</code>) using FX rates before summing into Net Worth, History, and Family Wealth analytics instead of adding raw balances across currencies.</li></ul>',47)])])}const g=o(a,[["render",i]]);export{m as __pageData,g as default};
